      tableName
    }
  }];
}

// Build ALTER TABLE statements
const alterStatements = columnsToAdd.map(field => 
  `ALTER TABLE "${tableName}" ADD COLUMN IF NOT EXISTS "${field.name}" ${field.type};`
).join('\n');

return [{
  json: {
    hasNewColumns: true,
    operation: 'executeQuery',
    query: alterStatements,
    tableName,
