// Configuration
const TABLE_NAME = 'incoming_documents';
const PRIMARY_KEY = 'ID'; // Column to use for upsert matching (case-sensitive!)

// Extract all unique field names and infer types from input data
const fields = new Map();

for (const item of $input.all()) {
  for (const [key, value] of Object.entries(item.json)) {
    if (!fields.has(key)) {
      // Infer PostgreSQL data type
      let pgType = 'TEXT'; // default

      // Skip empty strings for type inference
      if (value !== null && value !== undefined && value !== '') {
        if (typeof value === 'number') {
          pgType = Number.isInteger(value) ? 'INTEGER' : 'NUMERIC';
        } else if (typeof value === 'boolean') {
          pgType = 'BOOLEAN';
        } else if (value instanceof Date || /^\d{4}-\d{2}-\d{2}/.test(value)) {
          pgType = 'TIMESTAMP';
        } else if (typeof value === 'object' && value !== null) {
          pgType = 'JSONB';
        }
      }

      fields.set(key, pgType);
    }
  }
}

// Prepare output
return [{
  json: {
    tableName: TABLE_NAME,
    primaryKey: PRIMARY_KEY,
    fields: Array.from(fields.entries()).map(([name, type]) => ({
      name,
      type,
      isPrimaryKey: name === PRIMARY_KEY
    })),
    inputData: $input.all().map(item => item.json)
  }
}];

const { tableName, fields } = $input.first().json;

// Build CREATE TABLE IF NOT EXISTS statement
