const tableName = $('1. Analyze Input Data').first().json.tableName;
const primaryKey = $('1. Analyze Input Data').first().json.primaryKey;
const inputData = $('1. Analyze Input Data').first().json.inputData;
const fields = $('1. Analyze Input Data').first().json.fields;

// Configuration
const BATCH_SIZE = 100; // Adjust this based on your needs (100-500 rows per batch is typical)

// Build batched UPSERT statements
const batches = [];
let currentBatch = [];
let currentBatchSize = 0;

for (const row of inputData) {
  const columns = Object.keys(row);

  // Map values with proper type handling
  const values = columns.map(key => {
    const val = row[key];
    const field = fields.find(f => f.name === key);

    // Handle NULL/undefined/empty strings
    if (val === null || val === undefined || val === '') {
      return 'NULL';
    }

    // Handle by actual JavaScript type
    if (typeof val === 'number') return val;
    if (typeof val === 'boolean') return val;
    if (typeof val === 'object') return `'${JSON.stringify(val).replace(/'/g, "''")}'::jsonb`;

    // Handle string values that need to go into boolean columns
    if (field && field.type === 'BOOLEAN') {
      const lowerVal = String(val).toLowerCase().trim();
      if (lowerVal === 'true' || lowerVal === '1' || lowerVal === 'yes') return 'TRUE';
      if (lowerVal === 'false' || lowerVal === '0' || lowerVal === 'no') return 'FALSE';
      return 'NULL'; // Any other string becomes NULL for boolean columns
    }

    // Default: treat as text
    return `'${String(val).replace(/'/g, "''")}'`;
  });

  const updateSet = columns
    .filter(col => col !== primaryKey)
    .map(col => `"${col}" = EXCLUDED."${col}"`)
    .join(', ');

  const sql = `
INSERT INTO "${tableName}" (${columns.map(c => `"${c}"`).join(', ')})
VALUES (${values.join(', ')})
ON CONFLICT ("${primaryKey}") 
DO UPDATE SET ${updateSet};
  `;

  currentBatch.push(sql);
  currentBatchSize++;

  // When batch is full, save it and start a new one
  if (currentBatchSize >= BATCH_SIZE) {
    batches.push({
      json: {
        operation: 'executeQuery',
        query: currentBatch.join('\n'),
        tableName,
        batchNumber: batches.length + 1,
        rowCount: currentBatchSize
      }
    });
    currentBatch = [];
    currentBatchSize = 0;
  }
}

// Add remaining rows as final batch
if (currentBatch.length > 0) {
  batches.push({
    json: {
      operation: 'executeQuery',
      query: currentBatch.join('\n'),
      tableName,
      batchNumber: batches.length + 1,
      rowCount: currentBatchSize
    }
  });
}

return batches;

// Loop over input items and add a new field called 'myNewField' to the JSON of each one

function compareRows(cachedRow, currentRow) {
  const result = {
    needsUpdate: false,
    updates: []
  };

  // Handle null/undefined cases
  if (!cachedRow && currentRow) {
    result.needsUpdate = true;
    Object.keys(currentRow).forEach(key => {
      result.updates.push({
        key: key,
        currentValue: currentRow[key],
        cachedValue: undefined
      });
    });
    return result;
  }

  if (!currentRow) {
    return result; // No update needed if current row doesn't exist
  }

  // Get all unique keys from both objects
  const allKeys = new Set([
    ...Object.keys(cachedRow || {}),
    ...Object.keys(currentRow || {})
  ]);

  // Compare each key
  allKeys.forEach(key => {
    const cachedValue = cachedRow?.[key];
    const currentValue = currentRow?.[key];

    // Compare values (handles strings, numbers, booleans, null, undefined)
    if (cachedValue !== currentValue) {
      result.needsUpdate = true;
      result.updates.push({
        key: key,
        currentValue: currentValue,
        cachedValue: cachedValue
      });
    }
  });

  return result;
}

