// =============================================================================
// "Update Local Table" - Fixed & Optimized
// Output: one item per row that needs upsert, formatted as a flat object
//         ready to feed directly into a Postgres Upsert node.
// =============================================================================

// ── Helpers ──────────────────────────────────────────────────────────────────

/**
 * Normalise a value coming from Postgres (which stores everything as text)
 * so it can be fairly compared against a value coming from Google Sheets
 * (which may be a real boolean / number / null).
 *
 * Rules applied to the DB/cache side only – the GSheet value is the source
 * of truth and is left untouched.
 */
function normaliseDbValue(v) {
  if (v === null || v === undefined) return "";   // DB NULLs → treat as empty
  if (v === "true")  return true;
  if (v === "false") return false;
  // Numbers stored as strings ("4255", "-64116", "168356.09") → number
  if (typeof v === "string" && v !== "" && !isNaN(Number(v))) return Number(v);
  return v;
}

/**
 * Return true when the two values are meaningfully different.
 * Treats (null / undefined / "") as all equivalent so minor DB/GSheet
 * representation differences don't create spurious updates.
 */
function isDifferent(dbVal, gsVal) {
  const normDb = normaliseDbValue(dbVal);
  // Treat empty-ish values on the GSheet side the same way
  const normGs = (gsVal === null || gsVal === undefined) ? "" : gsVal;
  return normDb !== normGs;
}

// ── Read inputs ───────────────────────────────────────────────────────────────

const gsheetRows  = $("Google Sheets Trigger").all().map(i => i.json);
const cachedRows  = $("Select rows from a table1").all().map(i => i.json);
const noCache     = $("No Cache").isExecuted;

// ── Assign row_number in test mode ────────────────────────────────────────────
// In production the GSheet trigger supplies row_number; in test/pinned mode
// it does not.  We cannot use a sequential index because it won't match
// the DB's row_number.  We rely on ID matching instead (see below), so in
// test mode we just ensure the field exists (value doesn't matter for matching).
if ($execution.mode === "test") {
  if (!gsheetRows[0]?.row_number) {
    gsheetRows.forEach((row, i) => { row.row_number = i; });
  }
} else if (!gsheetRows[0]?.row_number) {
  throw new Error("GSheet trigger must provide row_number in production mode.");
}

// ── If there is no cache yet, nothing to diff – let the full-refresh path run ─
// (The caller knows noCache === true and will trigger a full reload.)
if (noCache) {
  return [];
}

// ── Build lookup: ID → cached row ─────────────────────────────────────────────
// BUG FIX #1: original code matched by row_number, but DB row_numbers start at 2
// and GSheet row_numbers are 0-based in test mode → they NEVER matched.
// Matching by the stable unique ID field is correct and position-independent.
const cachedById = {};
for (const row of cachedRows) {
  if (row.ID) cachedById[row.ID] = row;
}

// ── Compare and build upsert payloads ─────────────────────────────────────────
const upserts = [];

for (const gsRow of gsheetRows) {
  const cachedRow = cachedById[gsRow.ID];   // may be undefined → new row

  if (!cachedRow) {
    // ── New row: insert everything ──────────────────────────────────────────
    // Output the GSheet row as-is (flat), which is exactly what a Postgres
    // Upsert node expects.
    upserts.push({ ...gsRow });
    continue;
  }

  // ── Existing row: check for changes ────────────────────────────────────────
  // BUG FIX #2: original code compared raw DB strings vs GSheet booleans/numbers
  // which produced spurious "needsUpdate" for every row regardless of real changes.
  let hasChange = false;
  const mergedRow = { ...cachedRow };   // start from the cached state

  const allKeys = new Set([
    ...Object.keys(cachedRow),
    ...Object.keys(gsRow),
  ]);

  for (const key of allKeys) {
    if (key === "row_number") continue;   // internal bookkeeping, skip
    if (isDifferent(cachedRow[key], gsRow[key])) {
      hasChange = true;
      mergedRow[key] = gsRow[key];        // apply the update
    }
  }

  if (hasChange) {
    // Output the merged (updated) flat row – Postgres Upsert will use ID
    // (or whatever conflict key you configure) to decide INSERT vs UPDATE.
    upserts.push(mergedRow);
  }
}

// ── Return one n8n item per upsert ────────────────────────────────────────────
// BUG FIX #3: original code returned { updates: { needsUpdate, updates: [...] } }
// which is unusable by a downstream Postgres node.
// We now return flat row objects, one per item, matching the table schema.
return upserts.map(row => ({ json: row }));

// =============================================================================
// "Update Local Table" - Returns only rows that need updating,
// with only the changed fields + change context (old/new values) + the row ID.
// Output shape per item:
// {
//   ID: "...",           ← always included so Postgres knows which row to update
//   row_number: N,       ← always included for reference
//   fields: {            ← only the fields that actually changed
//     FIELD_NAME: {
//       from: <cached/db value>,
//       to:   <new gsheet value>
//     }, ...
//   }
// }
// =============================================================================

// ── Helpers ───────────────────────────────────────────────────────────────────

/**
 * Postgres stores everything as text; GSheets returns native JS types.
 * Normalise the DB side so comparisons are meaningful.
 * null / undefined → "" (both mean "empty")
 * "true" / "false" → boolean
 * numeric strings  → number
 */
function normaliseDbValue(v) {
  if (v === null || v === undefined) return "";
  if (v === "true")  return true;
  if (v === "false") return false;
  if (typeof v === "string" && v !== "" && !isNaN(Number(v))) return Number(v);
  return v;
}

/** Treat null / undefined / "" as the same "empty" on the GSheet side too. */
function normaliseGsValue(v) {
  return (v === null || v === undefined) ? "" : v;
}

function isDifferent(dbVal, gsVal) {
  return normaliseDbValue(dbVal) !== normaliseGsValue(gsVal);
}

// ── Read inputs ───────────────────────────────────────────────────────────────

const gsheetRows = $("Google Sheets Trigger").all().map(i => i.json);
const cachedRows = $("Select rows from a table1").all().map(i => i.json);
const noCache    = $("No Cache").isExecuted;

// In test/pinned mode the trigger doesn't supply row_number – assign a
// placeholder so the field exists (matching is done by ID, not row_number).
if ($execution.mode === "test") {
  if (!gsheetRows[0]?.row_number) {
    gsheetRows.forEach((row, i) => { row.row_number = i; });
  }
} else if (!gsheetRows[0]?.row_number) {
  throw new Error("GSheet trigger must provide row_number in production mode.");
}

// No cache → nothing to diff; let the full-refresh path handle it.
if (noCache) return [];

// ── Build ID → cached row lookup ──────────────────────────────────────────────
const cachedById = {};
for (const row of cachedRows) {
  if (row.ID) cachedById[row.ID] = row;
}

// ── Diff and collect only rows/fields that changed ───────────────────────────
const upserts = [];

for (const gsRow of gsheetRows) {
  const cachedRow = cachedById[gsRow.ID];

  // No cached row → skip (new insert, not an update)
  if (!cachedRow) continue;

  const changedFields = {};

  const allKeys = new Set([
    ...Object.keys(cachedRow),
    ...Object.keys(gsRow),
  ]);

  for (const key of allKeys) {
    if (key === "row_number") continue;  // bookkeeping only, never upsert this
    if (isDifferent(cachedRow[key], gsRow[key])) {
      changedFields[key] = {
        from: normaliseDbValue(cachedRow[key]),
        to:   normaliseGsValue(gsRow[key]),
      };
    }
  }

  if (Object.keys(changedFields).length === 0) continue;  // nothing changed

  upserts.push({
    json: {
      ID:         gsRow.ID,
      row_number: gsRow.row_number,
      fields:     changedFields,
    }
  });
}

return upserts;

const tableName = $('1. Analyze Input Data').first().json.tableName;
const primaryKey = $('1. Analyze Input Data').first().json.primaryKey;
const inputData = $('1. Analyze Input Data').first().json.inputData;

// Build UPSERT (INSERT ... ON CONFLICT) statements
const upsertStatements = [];

for (const row of inputData) {
  const columns = Object.keys(row);
  const values = Object.values(row).map(val => {
    if (val === null || val === undefined) return 'NULL';
    if (typeof val === 'number') return val;
    if (typeof val === 'boolean') return val;
    if (typeof val === 'object') return `'${JSON.stringify(val).replace(/'/g, "''")}'::jsonb`;
    return `'${String(val).replace(/'/g, "''")}'`;
  });

  const updateSet = columns
    .filter(col => col !== primaryKey)
    .map(col => `"${col}" = EXCLUDED."${col}"`)
    .join(', ');

  const sql = `
INSERT INTO "${tableName}" (${columns.map(c => `"${c}"`).join(', ')})
VALUES (${values.join(', ')})
ON CONFLICT ("${primaryKey}") 
DO UPDATE SET ${updateSet};
  `;

  upsertStatements.push(sql);
}

return [{
  json: {
    operation: 'executeQuery',
    query: upsertStatements.join('\n'),
    tableName,
    rowCount: inputData.length
  }
}];

// =============================================================================
// "Update Local Table" - Returns only rows with genuine changes,
// each item containing only the truly changed fields + from/to context.
// =============================================================================

// ── Helpers ───────────────────────────────────────────────────────────────────

function excelSerialToISO(serial) {
  const date = new Date((serial - 25569) * 86400 * 1000);
  return date.toISOString().split("T")[0];
}

function normalise(v) {
  if (v === null || v === undefined || v === false || v === "false" || v === 0) return "";
  if (v === true || v === "true") return true;

  if (typeof v === "string" && v !== "" && !isNaN(Number(v))) v = Number(v);

  if (typeof v === "number" && Number.isInteger(v) && v >= 40000 && v <= 60000)
    return excelSerialToISO(v);

  return v;
}

// ── Read inputs ───────────────────────────────────────────────────────────────

const schemaKeys  = new Set(Object.keys($("Config").last().json.schema?.properties || {}));
const cachedById  = Object.fromEntries(
  $("Select rows from a table1").all()
    .map(i => i.json)
    .filter(r => r.ID)
    .map(r => [r.ID, r])
);

const gsheetRows = $("Google Sheets Trigger").all().map(i => i.json);

if ($execution.mode === "test") {
  gsheetRows.forEach((row, i) => { row.row_number ??= i+2; });
} else if (!gsheetRows[0]?.row_number) {
  throw new Error("GSheet trigger must provide row_number in production mode.");
}

// ── Diff ──────────────────────────────────────────────────────────────────────

const upserts = [];

for (const gsRow of gsheetRows) {
  const cachedRow = cachedById[gsRow.ID];
  if (!cachedRow) continue;

  const changedFields = {};

  for (const key of schemaKeys) {
    const from = normalise(cachedRow[key]);
    const to   = normalise(gsRow[key]);
    if (from !== to) changedFields[key] = { from, to };
  }

  if (!Object.keys(changedFields).length) continue;

  upserts.push({
    json: {
      ID:         gsRow.ID,
      row_number: gsRow.row_number,
      fields:     changedFields,
      flatten_upsert: {
        ID:         gsRow.ID,
        row_number: gsRow.row_number,
        ...Object.fromEntries(Object.entries(changedFields).map(([k, v]) => [k, v.to]))
      }
    }
  });
}

return upserts;

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json = item.json.flatten_upsert;
}

return $input.all();

// ============================================================================
// PRODUCTION-READY GOOGLE SHEETS BATCH UPDATE WITH CREATE SUPPORT
// ============================================================================

// --- Configuration ---
const CONFIG = {
  sheetName: $("Config").last().json.sheet_name,
  idColumn: 'ID',
  maxUpdatesPerBatch: 500,
  validateHeaders: true,
  strictMode: true,
  matchingFields: {
    primary: ['COMPANY_ID', 'COMPANY_DOC_ID'],
    secondary: 'HASH'
  }
};

// --- Helper Functions ---

function columnToLetter(column) {
  if (column < 0) {
    throw new Error(`Invalid column index: ${column}`);
  }

  let letter = '';
  let temp = column;

  while (temp >= 0) {
    letter = String.fromCharCode((temp % 26) + 65) + letter;
    temp = Math.floor(temp / 26) - 1;
  }

  return letter;
}

function validateColumns(headerMap, updateItems) {
  const errors = [];
  const requiredColumns = new Set();

  updateItems.forEach(item => {
    Object.keys(item).forEach(key => requiredColumns.add(key));
  });

  requiredColumns.forEach(col => {
    if (col !== CONFIG.idColumn && headerMap[col] === undefined) {
