// ── Helpers ───────────────────────────────────────────────────────────────────

/**
 * Convert an Excel date serial (integer) to ISO date string "YYYY-MM-DD".
 * GSheets stores dates as Excel serials; Postgres stores them as ISO strings.
 * Excel epoch = 1900-01-01 with the classic Lotus-123 leap-year bug,
 * so the Unix-epoch offset is 25569 days.
 */
function excelSerialToISO(serial) {
  if (typeof serial !== "number" || serial < 1) return null;
  const date = new Date((serial - 25569) * 86400 * 1000);
  return date.toISOString().split("T")[0];
}

/** Return true when a value looks like an Excel date serial.
 *  Heuristic: integer between 40000 (2009) and 60000 (2064). */
function isExcelSerial(v) {
  return typeof v === "number" && Number.isInteger(v) && v >= 40000 && v <= 60000;
}

/**
 * Normalise a value to a canonical comparable form.
 *
 * Rules (applied to BOTH sides so the type domain is identical):
 *  - null / undefined / false / "false" / 0  → ""   (all mean "empty/unset")
 *  - "true" / true                            → true
 *  - numeric string                           → number
 *  - Excel date serial (number 40000-60000)   → "YYYY-MM-DD" ISO string
 *  - everything else                          → as-is
 *
 * Applying the same function to both sides means a DB "8516000" (string→number)
 * and a GSheet "8516000" (string→number) both become the number 8516000 and
 * compare equal — no false positive.
 */
function normalise(v) {
  // Treat all "empty / unset" sentinels the same
  if (v === null || v === undefined || v === false || v === "false" || v === 0)
    return "";

  if (v === true  || v === "true")  return true;

  // Numeric string → number  (before the Excel-serial check so "45698" → 45698
  // and then falls through to the serial check below)
  if (typeof v === "string" && v !== "" && !isNaN(Number(v))) {
    v = Number(v);
  }

  // Excel date serial → ISO string
  if (isExcelSerial(v)) return excelSerialToISO(v);

  return v;
}

function isDifferent(dbVal, gsVal) {
  return normalise(dbVal) !== normalise(gsVal);
}

